//! Host sides of the guest proxy libraries (NBS `libnative_bridge_guest_*`: libEGL, libGLESv1_CM, libGLESv2, libGLESv3, libnativewindow). Each proxy export is an interceptable stub that the guest's init binds through `native_bridge_intercept_symbol(addr, library, name)`.
//! `table` (generated by build.rs from the NBS stub lists and the EGL/GLES prototypes of two views) gives each (library, name) one entry: `Generic` (the host front's symbol, through the generic crossing) or `Trap(i)` (a named trap, aborting when called: unbound, or pending a binding class of GS2.2).
//! Resolution is per library: the front is looked up by `dlsym` on its own handle, never `RTLD_DEFAULT` (the global scope can hold another GL, e.g. Mesa's own export).

use std::collections::BTreeMap;
use std::ffi::{CString, c_void};
use std::sync::Mutex;

use super::unsupported;

mod table {
    include!(concat!(env!("OUT_DIR"), "/proxy_table.rs"));
}

/// What a stub binds to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Entry {
    /// the host front's symbol of the stub's name
    Generic,
    /// `table::TRAPS[i]`
    Trap(usize),
}

/// A guest proxy library: its soname (what the guest's init passes to the intercept) and its stubs, in NBS list order.
pub struct Lib {
    pub soname: &'static str,
    pub stubs: &'static [(&'static str, Entry)],
}

/// Fixed bindings besides the proxies and libc: the NBS vdso's four entries and the linker's two hooks (vdso.rs `bind`, `bind_linker`).
const FIXED_BINDINGS: usize = 6;
/// The thunk pool: one per binding, rounded to a power of two (x86_64.rs `THUNKS`).
pub const THUNKS: usize = (table::STUB_COUNT + table::LIBC_STUB_COUNT + FIXED_BINDINGS).next_power_of_two();

/// A trapped stub: calling it aborts, naming the stub and why it is trapped.
extern "C" fn trap<const I: usize>() {
    let (lib, name, why) = table::TRAP_NAMES[I];
    unsupported(&format!("guest stub {lib}:{name} has no host binding ({why})"))
}

/// What a stub binds to, with its host address (a thunk is made of it by the caller).
pub enum Target {
    Host(usize),
    Trap(usize),
    /// no host symbol: the stub stays unbound
    Absent,
}

impl Target {
    /// The address the stub's thunk crosses to; None when absent.
    pub fn address(self) -> Option<usize> {
        match self {
            Target::Host(a) | Target::Trap(a) => Some(a),
            Target::Absent => None,
        }
    }
}

/// Per proxy library, stubs by outcome: [bound to the host, unbound trap, pending trap, absent], printed once the library's list is complete.
static REPORT: Mutex<BTreeMap<&'static str, [usize; 4]>> = Mutex::new(BTreeMap::new());

#[allow(
    clippy::print_stderr,
    reason = "the startup report: one line per proxy library, before any logger"
)]
fn report(lib: &'static Lib, outcome: usize) {
    let Ok(mut r) = REPORT.lock() else { return };
    let c = r.entry(lib.soname).or_insert([0; 4]);
    c[outcome] += 1;
    if c.iter().sum::<usize>() == lib.stubs.len() {
        eprintln!(
            "atl-native-bridge: proxy {}: {} bound to the host, {} unbound (trapped), {} pending a binding class (trapped), {} absent",
            lib.soname, c[0], c[1], c[2], c[3]
        );
    }
}

/// The host front `soname`, loaded by path from the system library directory the GL fronts are placed in (`with_gl_driver`); None when it is not there. The loaded copy is returned when the process already has it (same inode).
fn front(soname: &str) -> Option<usize> {
    static FRONTS: Mutex<BTreeMap<String, usize>> = Mutex::new(BTreeMap::new());
    let mut fronts = FRONTS.lock().ok()?;
    if let Some(&h) = fronts.get(soname) {
        return (h != 0).then_some(h);
    }
    let path = CString::new(format!("{}/{soname}", atl_android_paths::SYSTEM_LIB)).ok()?;
    // SAFETY: dlopen of a host front by its path; its constructors run here, on the calling host thread.
    let h = unsafe { libc::dlopen(path.as_ptr(), libc::RTLD_NOW) } as usize;
    fronts.insert(soname.to_owned(), h);
    (h != 0).then_some(h)
}

/// The front's own symbol `name`.
fn symbol(soname: &str, name: &str) -> Option<usize> {
    let h = front(soname)?;
    let c = CString::new(name).ok()?;
    // SAFETY: dlsym on the front's live handle with a NUL-terminated name.
    let p = unsafe { libc::dlsym(h as *mut c_void, c.as_ptr()) };
    (!p.is_null()).then_some(p as usize)
}

/// What `native_bridge_intercept_symbol(_, soname, name)` binds the guest stub to. None when `soname` is not a proxy library: the caller falls back to the libc table.
pub fn target(soname: &str, name: &str) -> Option<Target> {
    let lib = table::LIBS.iter().find(|l| l.soname == soname)?;
    let entry = lib.stubs.iter().find(|(n, _)| *n == name).map(|&(_, e)| e);
    let (t, outcome) = match entry {
        Some(Entry::Generic) => match symbol(lib.soname, name) {
            Some(a) => (Target::Host(a), 0),
            None => (Target::Absent, 3),
        },
        Some(Entry::Trap(i)) => {
            let why = table::TRAP_NAMES[i].2;
            let outcome = if why.starts_with("unbound") { 1 } else { 2 };
            (Target::Trap(table::TRAPS[i] as usize), outcome)
        }
        None => (Target::Absent, 3),
    };
    report(lib, outcome);
    Some(t)
}
